tasks = []    # each task is a [text, done] pair

while True:
    line = input("> ").strip()
    if line == "":
        continue
    parts = line.split(maxsplit=1)
    command = parts[0].lower()
    argument = parts[1].strip() if len(parts) > 1 else ""

    if command == "quit":
        done = 0
        for text, finished in tasks:
            if finished:
                done += 1
        print(f"Bye! {done} of {len(tasks)} done.")
        break
    elif command == "add":
        if argument == "":
            print("Nothing to add.")
        else:
            tasks.append([argument, False])
            print(f"Added #{len(tasks)}: {argument}")
    elif command == "list":
        if not tasks:
            print("Nothing to do.")
        for i, (text, finished) in enumerate(tasks, start=1):
            mark = "x" if finished else " "
            print(f"{i}. [{mark}] {text}")
    elif command in ("done", "undo", "remove"):
        if argument == "":
            print("Which task?")
        elif not argument.isdigit():
            print(f"Not a number: {argument}")
        elif not 1 <= int(argument) <= len(tasks):
            print(f"No task {int(argument)}")
        else:
            index = int(argument) - 1
            text = tasks[index][0]
            if command == "done":
                tasks[index][1] = True
                print(f"Done: {text}")
            elif command == "undo":
                tasks[index][1] = False
                print(f"Undone: {text}")
            else:
                tasks.pop(index)
                print(f"Removed: {text}")
    elif command == "clear":
        kept = []
        for task in tasks:
            if not task[1]:
                kept.append(task)
        cleared = len(tasks) - len(kept)
        tasks = kept
        print(f"Cleared {cleared} task(s).")
    else:
        print(f"Unknown command: {parts[0]}")
